import{_ as e,o as a,c as o,am as p}from"./chunks/framework._FJXuPhs.js";const m=JSON.parse('{"title":"Docker-compose安装","description":"","frontmatter":{"title":"Docker-compose安装","excerpt":"摘要","date":"2025-06-23 22:06:12","updated":"2025-06-23 22:06:12"},"headers":[],"relativePath":"部署&工具/Java 知识体系-容器部署/Docker Compose/Docker-compose安装.md","filePath":"部署&工具/Java 知识体系-容器部署/Docker Compose/Docker-compose安装.md","lastUpdated":null}'),n={name:"部署&工具/Java 知识体系-容器部署/Docker Compose/Docker-compose安装.md"};function c(t,s,l,i,r,d){return a(),o("div",null,[...s[0]||(s[0]=[p(`<h3 id="离线安装" tabindex="-1">离线安装 <a class="header-anchor" href="#离线安装" aria-label="Permalink to &quot;离线安装&quot;">​</a></h3><p>Compose 是用于定义和运行多容器 Docker 应用程序的工具。通过 Compose，您可以使用 YML 文件来配置应用程序需要的所有服务。</p><p>使用一个命令，就可以从 YML 文件配置中创建并启动所有服务</p><blockquote><p>安装操作</p></blockquote><p>先需要下载一下二进制文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/docker/compose/releases/download/v2.5.0/docker-compose-linux-x86_64</span></span></code></pre></div><p>放入/usr/local/bin/ 路径下并重新命名添加可执行权限</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mv docker-compose-linux-x86_64 docker-compose</span></span>
<span class="line"><span>chmod +x docker-compose</span></span></code></pre></div><p>这个也可以推荐看一下</p><p>将脚本下载，阿里云的下载速度较快，推荐适用</p><p><a href="https://mirrors.aliyun.com/docker-toolbox/linux/compose/1.21.2/" target="_blank" rel="noreferrer">https://mirrors.aliyun.com/docker-toolbox/linux/compose/1.21.2/</a></p><p>把脚本放在/usr/local/bin/下.名字为docker-compose ,加执行权限 ，docker-compose命令就有了</p><h3 id="从github直接下载" tabindex="-1">从Github直接下载 <a class="header-anchor" href="#从github直接下载" aria-label="Permalink to &quot;从Github直接下载&quot;">​</a></h3><p>放弃</p><p>方式一：从Github直接下载</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 下载最新稳定版（替换版本号） </span></span>
<span class="line"><span>sudo curl -L &quot;https://github.com/docker/compose/releases/download/v2.23.0/docker-compose-$(uname -s)-$(uname -m)&quot; -o /usr/local/bin/docker-compose </span></span>
<span class="line"><span></span></span>
<span class="line"><span># 赋予执行权限 </span></span>
<span class="line"><span>sudo chmod +x /usr/local/bin/docker-compose</span></span></code></pre></div><p>镜像地址</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 指定路径【推荐】</span></span>
<span class="line"><span>sudo curl -L https://gitee.com/fustack/docker-compose/releases/download/v2.24.1/docker-compose-linux-x86_64 -o /usr/local/bin/docker-compose</span></span>
<span class="line"><span># 设置权限</span></span>
<span class="line"><span>sudo chmod +x /usr/local/bin/docker-compose</span></span></code></pre></div><p>上面第一步下载不了：curl: (52) Empty reply from server</p><p>放弃</p>`,20)])])}const h=e(n,[["render",c]]);export{m as __pageData,h as default};
